import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, copyToClipboard, hasWritePrivilege, ObjectKeys, AccountYears } from "../../../stores/Utils";

import "./dashboard.css"
import { OpenModal } from "../../../components/DialogHRM";
import { areasIds, delete_location_area, getInventoryByQuery, getall_product, scan_location_production, sortProducts,  } from "../services/server_fetching";
import { SvgIcon_Cmpt,  } from "../../../components";
import DeleteAlert from "./deleteAlert";
import NoPrivilege from "./NoPrivilege";
import { LocationsLabelsPdf } from "../services/export_service";


const Svg = SvgIcon_Cmpt();

// const UpdProduct = UpdProduct_Cmpt();



const LocationItem  = ({ data, updObserve }) => {
	

	
	const updObs =  () => {
		//set_obs(gen16CodeId())
	}



	const refreshAccs =  () => {
		scan_location_production(updObserve)
	}


	const update = async () => {
		if(hasWritePrivilege()){
			updStore("upd_product", data);
			updStore("upd_product_bck", JSON.parse(JSON.stringify(data)));
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			//modaldata["content"] = <UpdProduct confirm={refreshAccs} />;
			//OpenModal(modaldata);
		}
	}

	
	



	const deleteComprobante =  () => {
		delete_location_area(data?.areaLocationId, refreshAccs);
	}
	

	const OpenDeleteAlert = async () => {


		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege()){

			let invS = await getInventoryByQuery(data?.areaLocationId);

			let hasLinks = invS && ObjectKeys(invS).length>0;
			
			if(!hasLinks){
				
				if( Date.now() > lastTimeCallModal){
					updStore("lastTimeCallModal", Date.now()+320);
					let modaldata = {};
					modaldata["zIndex"] = 450;
					modaldata["height"] = "40vh";
					// data['observeResize']=true;
					modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
					modaldata["content"] = <DeleteAlert  label={"Eliminar Location"} confirm={deleteComprobante} item={data} />
					OpenModal(modaldata);
				}
			}
			else{
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				modaldata["content"] = <DeleteAlert label={"Tenemos un problema !!!"} body={"Existen registros de inventario associados a esta locacion"} btnConfirm={"OK"} />
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	

	const copyToClpb  =  ()  => {
		copyToClipboard( data?.areaId + "-" + data?.location);
	};


	const print  =  ()  => {
		LocationsLabelsPdf( [data]);
	};

	
	
	return (
		<div className="item_acc">
			<div className="_dsplFlx item_box product_header centerBx">
			
				<div className="_dsplFlx tr_bar_80">
					<div className="code tr_bar_40" onClick={copyToClpb}>
						{areasIds[data?.areaId]}
					</div>
					<div className="name tr_bar_20"   onClick={update}>
						{data?.location}
					</div>
					
				</div>
				<div className="flexSpace"/>
				<div className="icon" style={{marginLeft: 19}} onClick={print}>
					<Svg name={"printer"} color={"#646cff"}/>
				</div>
				{hasWritePrivilege()?
				AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<div className="icon" style={{marginLeft: 19}} onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				:null}
			</div>
			
		</div>
	)
}
export default LocationItem;